const raw = ($json.candidates?.[0]?.content?.parts || []).map((p) => p.text || '').join('');
const d = JSON.parse(raw);
const clean = (s) => String(s || '').replace(/\*/g, '').trim();
const ads = { content: clean(d.content), image_prompt: clean(d.image_prompt), image_text: clean(d.image_text).toUpperCase(), subheadline: clean(d.subheadline), benefits: (d.benefits || []).map(clean).filter(Boolean).slice(0, 3), cta: clean(d.cta).toUpperCase() || 'ĐĂNG KÝ TƯ VẤN' };
if (!ads.content || !ads.image_prompt) throw new Error('Gemini trả thiếu nội dung');
// gemini-3.8-flash (key trả phí) hay trả content dồn một đoạn: tự xuống dòng trước mỗi icon đứng sau dấu câu
if (!ads.content.includes('\n')) ads.content = ads.content.replace(/([.!?:])\s+(?=\p{Extended_Pictographic})/gu, '$1\n').replace(/\s+(?=[✔✅☑]\uFE0F?)/gu, '\n');
ads.manager_photo = /#quanly/i.test($('When Called').first().json.brief || '') ? '<ANH_CA_NHAN_DA_LUOC_BO>' : null;
ads.manager_face = ads.manager_photo ? '<ANH_CA_NHAN_DA_LUOC_BO>' : null;
return [{ json: ads }];

// Ảnh AI + header/footer nhận diện để bước sau ghép lại
// Có lần tạo lại thì dùng ảnh tạo lại (nếu tạo lại lỗi thì quay về ảnh đầu); check: ok | wrong | unchecked
const pick = (n) => { try { return ($(n).all(0)[0].json.candidates?.[0]?.content?.parts || []).find((p) => p.inlineData?.data) || null; } catch (e) { return null; } };
const verdict = (n) => { try { const j = $(n).all(0)[0].json; if (j.error) return null; return JSON.parse((j.candidates?.[0]?.content?.parts || []).map((p) => p.text || '').join('')); } catch (e) { return null; } };
let img = pick('Generate Retry'), v = verdict('Check Retry Paid') || verdict('Check Retry');
if (!img) { img = pick('Generate Image'); v = verdict('Check Text Paid') || verdict('Check Text'); }
if (!img) throw new Error('Gemini không trả ảnh');
let check = !v ? 'unchecked' : v.ok ? 'ok' : 'wrong';
let wrong = (v && v.wrong) || '';
if (v && v.headline_top && v.headline_top < 164) { check = 'wrong'; wrong = [wrong, 'tiêu đề bị khung logo che'].filter(Boolean).join('; '); }
if (v && v.same_person === false) { check = 'wrong'; wrong = [wrong, 'khuôn mặt quản lý chưa giống ảnh gốc'].filter(Boolean).join('; '); }
// Đẩy ảnh lên vừa đủ để nút CTA cách footer, không đẩy tiêu đề vào vùng logo; không đo được thì đẩy nhẹ
let shift = 27;
if (v && v.button_bottom) {
  const need = v.button_bottom * 1.08 + 60 - 972;
  const room = (v.headline_top || 1000) * 1.08 - 189;
  shift = Math.round(Math.max(0, Math.min(need, room, 100)));
}
const ext = img.inlineData.mimeType === 'image/png' ? 'png' : 'jpg';
const header = '';
const footer = '';
return [{ json: { check, wrong, shift }, binary: {
  file: { data: img.inlineData.data, mimeType: img.inlineData.mimeType, fileName: 'ai.' + ext, fileExtension: ext },
  header: { data: header, mimeType: 'image/png', fileName: 'header.png', fileExtension: 'png' },
  footer: { data: footer, mimeType: 'image/png', fileName: 'footer.png', fileExtension: 'png' },
  canvas: { data: '', mimeType: 'image/png', fileName: 'ads.png', fileExtension: 'png' },
} }];

// Tin 1: ảnh kèm chú thích ngắn; các tin sau: content + footer (Zalo giới hạn 2000 ký tự/tin)
// Tạo/upload ảnh lỗi thì vẫn gửi content để người dùng không phải chờ lại từ đầu
const footer = "---***---\nCÔNG TY TNHH GOSTECH\nGiải pháp phát triển doanh nghiệp\n📍 Trụ sở chính: Số nhà 11, ngõ 245/116/27 Phố Định Công, Phường Định Công, Hà Nội\n📍 Văn phòng: Tòa A3 Vinhomes Hàm Nghi, Phường Từ Liêm, Hà Nội\n📞 Hotline: 0968 343 342\n🌐 Website: gostech.vn | hocviendigital.vn";
const ads = $('Parse Ads').all(0)[0].json;
const brief = ($('When Called').first().json.brief || '').replace(/#quanly/gi, '').trim().replace(/[\s.]*Cảnh\s*:[\s\S]*$/i, '').trim();
let att = null;
try { att = $('Upload Image').all(0)[0].json.data?.attachment_id || null; } catch (e) {}
let chk = {};
try { chk = $('To File').all(0)[0]?.json || {}; } catch (e) {}
const warn = chk.check === 'wrong' ? '\n⚠️ AI kiểm tra thấy ảnh có thể có lỗi: ' + chk.wrong + '. Bạn xem kỹ trước khi dùng hoặc gõ lại /ads.'
  : chk.check === 'unchecked' ? '\nℹ️ Chưa kiểm tra được chính tả trên ảnh, bạn xem lại trước khi dùng.' : '';
const msgs = [];
if (att) msgs.push({ text: '🖼️ Ảnh quảng cáo cho: ' + (brief.length > 150 ? brief.slice(0, 150) + '...' : brief) + warn, attachment: { type: 'template', payload: { template_type: 'media', elements: [{ media_type: 'image', attachment_id: att }] } } });
const note = att ? '' : '⚠️ Lần này chưa tạo được ảnh, gửi trước phần content. Bạn gõ lại lệnh /ads để thử tạo ảnh.\n\n';
const text = (note + ads.content + '\n\n' + footer).trim();
const max = 1900;
let cur = '';
for (const para of text.split(/\n{2,}/)) {
  const joined = cur ? cur + '\n\n' + para : para;
  if (joined.length <= max) { cur = joined; continue; }
  if (cur) msgs.push({ text: cur });
  cur = '';
  if (para.length <= max) { cur = para; continue; }
  for (let i = 0; i < para.length; i += max) msgs.push({ text: para.slice(i, i + max) });
}
if (cur) msgs.push({ text: cur });
return msgs.map((message) => ({ json: { message } }));
